/**
 * Token helpers shared by the build script, the contrast check and Storybook (A-10-T03/T04).
 * Pure functions only — no Node APIs — so the browser (Storybook) can import them.
 */

const HEADER =
  "/* Generated by packages/ui/scripts/build-tokens.mjs from tokens/tokens.json — do not edit. */\n";

/** `fontFamily` → `font-family`, `2xl` stays, `0-5` stays. */
export function kebab(name) {
  return String(name)
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .toLowerCase();
}

/** Every token (a node with `$value`) as { path: string[], type, value }; `$type` is inherited. */
export function flatten(node, path = [], inheritedType = undefined) {
  const type = node.$type ?? inheritedType;
  if (Object.prototype.hasOwnProperty.call(node, "$value")) {
    return [{ path, type, value: node.$value }];
  }
  return Object.entries(node)
    .filter(([key]) => !key.startsWith("$"))
    .flatMap(([key, child]) => flatten(child, [...path, key], type));
}

/** CSS custom property for a token path: semantic tokens drop the `semantic` group and `default`. */
export function cssVar(path) {
  const parts = path[0] === "semantic" ? path.slice(1) : path;
  const trimmed = parts.length > 1 && parts.at(-1) === "default" ? parts.slice(0, -1) : parts;
  return `--n9-${trimmed.map(kebab).join("-")}`;
}

const ALIAS = /^\{([^}]+)\}$/;

/** Resolve `{a.b.c}` aliases to their final literal value (throws on unknown or circular refs). */
export function resolveAlias(tokens, value, seen = new Set()) {
  const match = typeof value === "string" ? ALIAS.exec(value) : null;
  if (!match) return value;
  const ref = match[1];
  if (seen.has(ref)) throw new Error(`circular token alias: ${[...seen, ref].join(" → ")}`);
  const target = tokens.find((token) => token.path.join(".") === ref);
  if (!target) throw new Error(`unknown token alias {${ref}}`);
  return resolveAlias(tokens, target.value, new Set([...seen, ref]));
}

function quoteFamily(name) {
  return /^[a-z-]+$/i.test(name) && !name.includes(" ") ? name : `"${name}"`;
}

/** Hex colours are written in lower case (Prettier's CSS style), so generated files stay stable. */
const hex = (value) => (/^#[0-9a-f]+$/i.test(value) ? value.toLowerCase() : value);

/** CSS text for one token value; aliases become `var(--n9-…)`. */
export function cssValue(token) {
  const { type, value } = token;
  const match = typeof value === "string" ? ALIAS.exec(value) : null;
  if (match) return `var(${cssVar(match[1].split("."))})`;
  switch (type) {
    case "fontFamily":
      return (Array.isArray(value) ? value : [value]).map(quoteFamily).join(", ");
    case "shadow":
      return (Array.isArray(value) ? value : [value])
        .map((s) => `${s.offsetX} ${s.offsetY} ${s.blur} ${s.spread} ${hex(s.color)}`)
        .join(", ");
    case "cubicBezier":
      return `cubic-bezier(${value.join(", ")})`;
    default:
      return hex(String(value));
  }
}

export function renderTokensCss(tokens) {
  for (const token of tokens) resolveAlias(tokens, token.value); // fail fast on broken aliases
  const lines = tokens.map((token) => `  ${cssVar(token.path)}: ${cssValue(token)};`);
  return `${HEADER}:root {\n${lines.join("\n")}\n}\n`;
}

/** Tailwind theme variable name for a token, or null when the token is not exposed to Tailwind. */
export function themeVar(path) {
  const [group, sub, ...rest] = path;
  const name = (parts) => parts.map(kebab).join("-");
  const tail = (parts) => (parts.length && parts.at(-1) !== "default" ? `-${name(parts)}` : "");
  switch (group) {
    case "color":
      return `--color-${name([sub, ...rest])}`;
    case "semantic": {
      const prefix = { surface: "surface", text: "fg", border: "border" }[sub];
      return prefix ? `--color-${prefix}${tail(rest)}` : null;
    }
    case "font":
      if (sub === "family") return `--font-${name(rest)}`;
      if (sub === "size") return `--text-${name(rest)}`;
      if (sub === "lineHeight") return `--text-${name(rest)}--line-height`;
      if (sub === "weight") return `--font-weight-${name(rest)}`;
      return null;
    case "radius":
      return `--radius-${name([sub])}`;
    case "elevation":
      return `--shadow-elevation-${name([sub])}`;
    case "size":
      return `--spacing-${name([sub])}`;
    case "breakpoint":
      return `--breakpoint-${name([sub])}`;
    case "motion":
      return sub === "easing" ? `--ease-${name(rest)}` : null;
    default:
      return null; // `space` is exposed through Tailwind's single --spacing step below
  }
}

export function renderThemeCss(tokens) {
  const lines = [
    "  /* Only token values exist: Tailwind's default palette and breakpoints are removed. */",
    "  --color-*: initial;",
    "  --breakpoint-*: initial;",
    "  --color-white: #ffffff;",
    "  --color-black: #000000;",
    "  /* 4 px grid: p-1 = space.1, p-3 = space.3 … */",
    `  --spacing: var(${cssVar(["space", "1"])});`,
  ];
  for (const token of tokens) {
    const name = themeVar(token.path);
    if (!name) continue;
    // Media queries cannot read custom properties, so breakpoints are written as literals.
    const value =
      token.path[0] === "breakpoint"
        ? resolveAlias(tokens, token.value)
        : `var(${cssVar(token.path)})`;
    lines.push(`  ${name}: ${value};`);
  }
  return `${HEADER}@theme inline {\n${lines.join("\n")}\n}\n`;
}
